import { describe, expect, it } from 'vitest';
import type { TaskEntry } from './contract';
import { abnahmeOf, allTicked, parseSheets, progress, rowsOf, tickItem, waiting } from './abnahme';

const BLOCK = [
  '<!-- testing:sheets:begin -->',
  '## Test sheets',
  '',
  '_Generated by `testing sheets report --tasks`; edit the sheet, not this block (ticked boxes are kept)._',
  '',
  '- **:UI option float** (`ui.option-float`, `ui.nvim/TESTS/sheets/ui-option-float.sheet.lua`): automated part green, waiting for your judgement',
  '  - Judge:',
  '    - [ ] The rows and texts of the float read well',
  '    - [x] The border is visible',
  '  - By hand:',
  '    - [ ] In the real config the cheatsheet key <M-h> opens the same float',
  '  - Look at: `ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/float.80x24.snap`, `ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/b.80x24.snap`',
  '- **Done sheet** (`ui.done`, `ui.nvim/TESTS/sheets/done.sheet.lua`): green',
  '  - Judge:',
  '    - [ ] Not waiting, the sheet is green',
  '<!-- testing:sheets:states ui.option-float=inbox ui.done=green -->',
  '<!-- testing:sheets:end -->',
].join('\n');

const body = (block: string) => `## Kontext\n\ntext\n\n${block}\n\n## Notizen\n`;

describe('the sheet block', () => {
  it('is read as sheets with their criteria, snapshots and the state of the states line', () => {
    const sheets = parseSheets(body(BLOCK));
    expect(sheets.map((s) => [s.id, s.state, s.title])).toEqual([
      ['ui.option-float', 'inbox', ':UI option float'],
      ['ui.done', 'green', 'Done sheet'],
    ]);
    const float = sheets[0]!;
    expect(float.items.map((i) => [i.kind, i.text, i.checked])).toEqual([
      ['judge', 'The rows and texts of the float read well', false],
      ['judge', 'The border is visible', true],
      ['manual', 'In the real config the cheatsheet key <M-h> opens the same float', false],
    ]);
    expect(float.snapshots).toEqual([
      'ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/float.80x24.snap',
      'ui.nvim/TESTS/__snapshots__/sheets/ui-option-float.sheet/b.80x24.snap',
    ]);
  });

  it('is not read when it is broken or missing', () => {
    expect(parseSheets('## Kontext\n- [ ] not a block\n')).toEqual([]);
    expect(parseSheets(body(BLOCK.replace('<!-- testing:sheets:end -->', '')))).toEqual([]);
    expect(parseSheets(body(`${BLOCK}\n${BLOCK}`))).toEqual([]);
  });

  it('waits for a person only in the sheets that are inbox or manual and have criteria', () => {
    const sheets = parseSheets(body(BLOCK));
    expect(waiting(sheets).map((s) => s.id)).toEqual(['ui.option-float']);
    expect(progress(sheets)).toEqual({ ticked: 1, total: 3 });
    expect(allTicked(sheets)).toBe(false);
  });

  it('offers done when every criterion of the waiting sheets is ticked, and not for a sheet without any', () => {
    const ticked = BLOCK.replaceAll('- [ ] The rows', '- [x] The rows').replace('- [ ] In the real', '- [x] In the real');
    expect(allTicked(parseSheets(body(ticked)))).toBe(true);
    const none = BLOCK.replace('ui.option-float=inbox', 'ui.option-float=green');
    expect(allTicked(parseSheets(body(none)))).toBe(false);
  });

  it('keeps the states of a sheet that does not load apart (it has no id)', () => {
    const broken = [
      '<!-- testing:sheets:begin -->',
      '- **ui.nvim/TESTS/sheets/x.sheet.lua** (`ui.nvim/TESTS/sheets/x.sheet.lua`): does not load',
      '<!-- testing:sheets:states x.sheet.lua=red -->',
      '<!-- testing:sheets:end -->',
    ].join('\n');
    const [sheet] = parseSheets(broken);
    expect(sheet?.id).toBeUndefined();
    expect(sheet?.state).toBeUndefined();
  });
});

describe('a tick', () => {
  it('changes the one line of the box and nothing else', () => {
    const text = body(BLOCK);
    const item = parseSheets(text)[0]!.items[0]!;
    const next = tickItem(text, item, true)!;
    expect(next.split('\n').filter((l, i) => l !== text.split('\n')[i])).toEqual([
      '    - [x] The rows and texts of the float read well',
    ]);
    expect(tickItem(next, { ...item }, false)).toBe(text);
  });

  it('is refused when the line is no longer that box (the body changed since it was read)', () => {
    const text = body(BLOCK);
    const item = parseSheets(text)[0]!.items[0]!;
    expect(tickItem(text, { line: item.line, text: 'another criterion' }, true)).toBeNull();
    expect(tickItem(text, { line: 0, text: item.text }, true)).toBeNull();
    expect(tickItem(text, { line: 9999, text: item.text }, true)).toBeNull();
  });

  it('keeps a carriage return of the line', () => {
    const text = body(BLOCK).replaceAll('\n', '\r\n');
    const sheets = parseSheets(text);
    const item = sheets[0]!.items[0]!;
    expect(item.text).toBe('The rows and texts of the float read well');
    expect(tickItem(text, item, true)).toContain('    - [x] The rows and texts of the float read well\r\n');
  });
});

describe('the tasks of the view', () => {
  const t = (id: string, state?: string) => ({ id, ...(state ? { sheets: { state } } : {}) }) as unknown as TaskEntry;

  it('are those whose sheets wait for a person', () => {
    expect(abnahmeOf([t('a', 'inbox'), t('b', 'red'), t('c'), t('d', 'manual'), t('e', 'green')]).map((x) => x.id)).toEqual(['a', 'd']);
  });

  it('show a snapshot as rows without the empty row after the last newline', () => {
    expect(rowsOf('one\r\ntwo\n')).toEqual(['one', 'two']);
    expect(rowsOf('')).toEqual(['']);
  });
});
